const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const V1_FIXTURE = JSON.parse(fs.readFileSync(
  path.join(ROOT, 'tests', 'fixtures', 'bench', 'schedule-v1-core-baseline-66.json'), 'utf8'));
const CORE_LOCK = JSON.parse(fs.readFileSync(path.join(ROOT, 'scripts', 'bench', 'tasks', 'core.lock.json'), 'utf8'));
const CORE_IDS = Object.freeze(CORE_LOCK.tasks.map((task) => task.id));
const GATE_FILE = path.join(ROOT, 'scripts', 'bench', 'gate', 'release-gate-v1.0.0.json');

// The committed gate re-serialized with another indent: valid, with different
// bytes and so a different sha256 (indent 2 gives the committed bytes).
function gateBytes(indent = 2) {
  return Buffer.from(`${JSON.stringify(JSON.parse(fs.readFileSync(GATE_FILE, 'utf8')), null, indent)}\n`, 'utf8');
}

function taskOrderByRound(schedule, rounds) {
  const out = [];
  for (let round = 1; round <= rounds; round += 1) {
    const seen = [];
    for (const entry of schedule) {
      if (entry.round === round && !seen.includes(entry.taskId)) seen.push(entry.taskId);
    }
    out.push(seen);
  }
  return out;
}

// --- V1 golden ---------------------------------------------------------------------

test('golden: buildSchedule without conditions deep-equals the committed V1 schedule', () => {
  assert.equal(CORE_IDS.length, 12, 'the frozen core set has 12 tasks');
  assert.deepEqual(V1_FIXTURE.args, {
    campaignId: 'core-baseline-66', taskIds: CORE_IDS, rounds: 10, arms: ['autopilot', 'claude'], seed: 66,
  });
  const schedule = buildSchedule({
    campaignId: 'core-baseline-66', taskIds: [...CORE_IDS], rounds: 10, arms: ['autopilot', 'claude'], seed: 66,
  });
  assert.equal(schedule.length, 240);
  assert.deepEqual(schedule, V1_FIXTURE.schedule);
  assert.equal(JSON.stringify(schedule), JSON.stringify(V1_FIXTURE.schedule), 'byte-identical, key order included');
  for (const entry of schedule) {
    assert.equal(Object.prototype.hasOwnProperty.call(entry, 'condition'), false, 'no condition key without conditions');
    assert.deepEqual(Object.keys(entry), ['campaignId', 'runId', 'round', 'order', 'taskId', 'arm']);
  }
});

test('golden: conditions undefined or null take the unchanged path', () => {
  const args = { campaignId: 'core-baseline-66', taskIds: [...CORE_IDS], rounds: 10, arms: ['autopilot', 'claude'], seed: 66 };
  assert.deepEqual(buildSchedule({ ...args, conditions: undefined }), V1_FIXTURE.schedule);
  assert.deepEqual(buildSchedule({ ...args, conditions: null }), V1_FIXTURE.schedule);
});

// --- Condition slots -----------------------------------------------------------------

test('conditions: autopilot off/on, 20 rounds, seed 71 gives 480 ABBA-interleaved entries', () => {
  const schedule = buildSchedule({
    campaignId: 'core-gate-71-autopilot', taskIds: [...CORE_IDS], rounds: 20, arms: ['autopilot'], conditions: ['off', 'on'], seed: 71,
  });
  assert.equal(schedule.length, 480);
  assert.deepEqual(schedule.map((entry) => entry.order), Array.from({ length: 480 }, (_, i) => i + 1));
  const seen = new Set(schedule.map((entry) => `${entry.round}|${entry.taskId}|${entry.condition}`));
  assert.equal(seen.size, 480, 'each (round, task, condition) exactly once');
  for (const entry of schedule) {
    assert.deepEqual(Object.keys(entry), ['campaignId', 'runId', 'round', 'order', 'taskId', 'arm', 'condition']);
    assert.ok(CONDITIONS.includes(entry.condition));
    assert.equal(entry.arm, 'autopilot');
    assert.equal(entry.runId, `core-gate-71-autopilot-r${entry.round}-${entry.taskId}-autopilot-${entry.condition}`);
    assert.match(entry.runId, /-autopilot-(?:off|on)$/);
  }
  for (let round = 1; round <= 20; round += 1) {
    const inRound = schedule.filter((entry) => entry.round === round);
    assert.equal(inRound.length, 24);
    for (let i = 0; i < inRound.length; i += 2) {
      assert.equal(inRound[i].taskId, inRound[i + 1].taskId, 'both conditions run a task back to back');
      const expected = round % 2 === 1 ? ['off', 'on'] : ['on', 'off'];
      assert.deepEqual([inRound[i].condition, inRound[i + 1].condition], expected);
    }
  }
});

test('conditions: two arms and two conditions give ABBA over (arm, condition) slots', () => {
  const schedule = buildSchedule({
    campaignId: 'c-2', taskIds: CORE_IDS.slice(0, 2), rounds: 2, arms: ['autopilot', 'claude'], conditions: ['off', 'on'], seed: 5,
  });
  assert.equal(schedule.length, 16);
  const slot = (entry) => `${entry.arm}/${entry.condition}`;
  assert.deepEqual(schedule.slice(0, 4).map(slot), ['autopilot/off', 'autopilot/on', 'claude/off', 'claude/on']);
  assert.deepEqual(schedule.slice(8, 12).map(slot), ['claude/on', 'claude/off', 'autopilot/on', 'autopilot/off']);
});

test('conditions: seed 66 with conditions [off] reproduces the V1 task order round by round', () => {
  const claude = buildSchedule({
    campaignId: 'core-gate-71-claude', taskIds: [...CORE_IDS], rounds: 30, arms: ['claude'], conditions: ['off'], seed: 66,
  });
  assert.equal(claude.length, 360);
  for (const entry of claude) {
    assert.equal(entry.condition, 'off');
    assert.match(entry.runId, /-claude-off$/);
  }
  const v1Order = taskOrderByRound(V1_FIXTURE.schedule, 10);
  const claudeOrder = taskOrderByRound(claude, 10);
  for (let round = 0; round < 10; round += 1) {
    assert.deepEqual(claudeOrder[round], v1Order[round], `round ${round + 1} task order matches V1`);
  }
});

test('conditions: invalid lists throw a TypeError naming conditions', () => {
  const base = { campaignId: 'c-3', taskIds: CORE_IDS.slice(0, 3), rounds: 1, arms: ['autopilot'], seed: 1 };
  for (const conditions of [[], ['off', 'off'], ['maybe'], 'off', ['on', 'ON'], [null], {}]) {
    assert.throws(() => buildSchedule({ ...base, conditions }), (error) => error instanceof TypeError && /conditions/.test(error.message),
      `conditions ${JSON.stringify(conditions)} must throw`);
  }
});

// --- Contract constants -----------------------------------------------------------

test('CONDITIONS, condition_not_applied and jev_measurement_missing join the run contract', () => {
  assert.ok(Object.isFrozen(CONDITIONS));
  assert.deepEqual([...CONDITIONS], ['off', 'on']);
  assert.ok(INFRA_CODES.includes('condition_not_applied'));
  assert.ok(PAUSING_INFRA_CODES.includes('condition_not_applied'));
  assert.deepEqual(pauseDecision(0, 'condition_not_applied'), { pause: 'condition_not_applied', consecutiveOther: 0 });
  assert.ok(RUN_FLAGS.includes('jev_measurement_missing'));
});

