const BOOLEAN_SETTING = async (client, key) => ({
  isError: false, json: { key, value: false, type: 'boolean', writable: true, range: null, values: null }, text: '',
});

test('71-03 condition preflight: a build without a boolean settings key, an armed capture or an unverifiable capture read is refused (exit 2, nothing written)', async () => {
  const cases = [
    ['the settings tool is missing (throws)', { readSetting: async () => { throw new Error('MCP error -32602: Tool settings not found'); } }, 'conditions_unsupported'],
    ['the settings tool answers isError', { readSetting: async () => ({ isError: true, json: null, text: 'SETTING_UNSUPPORTED' }) }, 'conditions_unsupported'],
    ['the key is not a boolean', { readSetting: async (client, key) => ({ isError: false, json: { key, value: 'false', type: 'string' }, text: '' }) }, 'conditions_unsupported'],
    ['the answer is not JSON', { readSetting: async () => ({ isError: false, json: null, text: 'no' }) }, 'conditions_unsupported'],
    ['the capture arm reads true', { readExtensionStorageFlag: async (port, id, key) => key === TELEMETRY_KEY || key === ARMED_KEY }, 'capture_armed'],
    ['the capture arm is unverifiable', { readExtensionStorageFlag: async (port, id, key) => (key === TELEMETRY_KEY ? true : null) }, 'capture_arm_unverifiable'],
  ];
  for (const [label, overrides, code] of cases) {
    for (const mode of ['smoke', 'preflight']) {
      const deps = liveDeps({ readSetting: BOOLEAN_SETTING, ...overrides });
      try {
        const args = mode === 'smoke'
          ? smokeArgs(deps, 'cond-preflight-refusal', ['--conditions', 'off,on'])
          : ['--preflight', '--arms', 'autopilot', '--expect-extension-id', VALID_EXTENSION_ID, '--chrome-profile', deps.localRoot, '--conditions', 'off,on'];
        const exit = await main(args, deps);
        assert.equal(exit, 2, `${label} (${mode}): ${deps.out.text()}`);
        assert.match(deps.out.text(), new RegExp(`\\b${code}\\b`), label);
        assert.equal(deps.calls.includes('writeSetting'), false, 'nothing is written');
        assert.equal(deps.calls.includes('startFixtureServer'), false, 'no run is scheduled');
        assert.deepEqual(filesUnder(deps.localRoot).filter((file) => file.endsWith('identity.json')), [], 'no identity is written');
        assert.equal(deps.wasClosed(), true, 'the runner client is closed');
      } finally {
        deps.cleanup();
      }
    }
  }
});

test('71-03 conditionPreflight: no CDP port or no extension id is conditions_unverifiable and reads nothing; the ok path reads the key, then the capture arm', async () => {
  const calls = [];
  const deps = { readSetting: spy('readSetting', calls), readExtensionStorageFlag: spy('readExtensionStorageFlag', calls) };
  const noId = { success: true, config: {}, extension: {} };
  for (const [cdpPort, expectExtensionId, payload] of [[null, VALID_EXTENSION_ID, CONFIG_PAYLOAD], [9222, null, noId], [null, null, noId]]) {
    const result = await conditionPreflight({ deps, options: { expectExtensionId }, client: {}, pre: { cdpPort, config: { ok: true, payload } } });
    assert.equal(result.ok, false);
    assert.deepEqual(result.refusals.map((refusal) => refusal.code), ['conditions_unverifiable']);
  }
  assert.deepEqual(calls, []);

  const seen = [];
  const ok = await conditionPreflight({
    deps: {
      readSetting: async (client, key) => { seen.push(['readSetting', client, key]); return BOOLEAN_SETTING(client, key); },
      readExtensionStorageFlag: async (port, id, key) => { seen.push(['cdp', port, id, key]); return false; },
    },
    options: { expectExtensionId: null },
    client: 'runner-client',
    pre: { cdpPort: 9222, config: { ok: true, payload: CONFIG_PAYLOAD } },
  });
  assert.equal(ok.ok, true);
  assert.deepEqual(ok.refusals, []);
  assert.equal(ok.cdpPort, 9222);
  assert.equal(ok.extensionId, VALID_EXTENSION_ID, 'the loaded extension id when none is expected');
  assert.deepEqual(seen, [['readSetting', 'runner-client', FAST_KEY], ['cdp', 9222, VALID_EXTENSION_ID, ARMED_KEY]]);
});

