test('71-03 mcp-client: writeSetting and readSetting call the settings tool with a string value and the short timeout', async () => {
  const seen = [];
  const client = {
    callTool: async (request, schema, opts) => {
      seen.push({ request, schema, opts });
      if (request.arguments.value === 'false') return { isError: true, content: [{ type: 'text', text: 'SETTING_UNAVAILABLE: The FSB extension did not confirm the settings change' }] };
      return { content: [{ type: 'text', text: JSON.stringify({ key: request.arguments.key, value: true, type: 'boolean' }) }] };
    },
  };
  const wrote = await writeSetting(client, FAST_KEY, true);
  const unconfirmed = await writeSetting(client, FAST_KEY, 'false');
  const read = await readSetting(client, FAST_KEY);
  assert.deepEqual(seen.map((call) => call.request), [
    { name: 'settings', arguments: { key: FAST_KEY, value: 'true' } },
    { name: 'settings', arguments: { key: FAST_KEY, value: 'false' } },
    { name: 'settings', arguments: { key: FAST_KEY } },
  ]);
  for (const call of seen) assert.deepEqual(call.opts, { timeout: 15000 });
  assert.equal(wrote.isError, false);
  assert.deepEqual(wrote.json, { key: FAST_KEY, value: true, type: 'boolean' });
  assert.equal(unconfirmed.isError, true);
  assert.equal(unconfirmed.json, null);
  assert.equal(read.json.type, 'boolean');
});

function applierWith({ stored, armed, write = null }) {
  const calls = [];
  const value = (result) => {
    if (result === 'throw') throw new Error('cdp_http_failed');
    return result;
  };
  const deps = {
    writeSetting: async (client, key, wireValue) => {
      calls.push(['writeSetting', client, key, wireValue]);
      if (write) return write();
      return { isError: false, json: { key, value: wireValue === 'true' }, text: '' };
    },
    readExtensionStorageFlag: async (port, id, key) => {
      calls.push(['read', port, id, key]);
      return value(key === FAST_KEY ? stored : armed);
    },
  };
  const client = { fake: 'runner-client' };
  return { calls, client, apply: createConditionApplier({ deps, client, cdpPort: 9333, extensionId: VALID_EXTENSION_ID }) };
}

test('71-03 createConditionApplier: writes through the settings tool, then the CDP readback and the capture arm decide', async () => {
  let harness = applierWith({ stored: true, armed: false });
  assert.deepEqual(await harness.apply('on'), { ok: true, reason: null });
  assert.deepEqual(harness.calls, [
    ['writeSetting', harness.client, FAST_KEY, 'true'],
    ['read', 9333, VALID_EXTENSION_ID, FAST_KEY],
    ['read', 9333, VALID_EXTENSION_ID, ARMED_KEY],
  ], 'one product-path write, then exactly the two storage reads');

  harness = applierWith({ stored: false, armed: false });
  assert.deepEqual(await harness.apply('off'), { ok: true, reason: null });
  assert.equal(harness.calls[0][3], 'false');

  for (const write of [() => ({ isError: true, json: null, text: 'SETTING_UNAVAILABLE' }), () => { throw new Error('request timed out'); }]) {
    harness = applierWith({ stored: true, armed: false, write });
    assert.deepEqual(await harness.apply('on'), { ok: true, reason: null }, 'the settings answer is ignored; the readback decides');
  }

  assert.deepEqual(await applierWith({ stored: false, armed: false }).apply('on'), { ok: false, reason: 'readback_mismatch' });
  assert.deepEqual(await applierWith({ stored: true, armed: false }).apply('off'), { ok: false, reason: 'readback_mismatch' });
  harness = applierWith({ stored: false, armed: false, write: () => ({ isError: false, json: { key: FAST_KEY, value: true, changed: true }, text: '' }) });
  assert.deepEqual(await harness.apply('on'), { ok: false, reason: 'readback_mismatch' }, 'a confirmed write the readback contradicts');

  for (const stored of [null, undefined, 'throw', 'true']) {
    assert.deepEqual(await applierWith({ stored, armed: false }).apply('on'), { ok: false, reason: 'unverifiable' }, `stored ${String(stored)}`);
  }
  for (const armed of [null, undefined, 'throw']) {
    assert.deepEqual(await applierWith({ stored: true, armed }).apply('on'), { ok: false, reason: 'unverifiable' }, `armed ${String(armed)}`);
  }
  assert.deepEqual(await applierWith({ stored: true, armed: true }).apply('on'), { ok: false, reason: 'capture_armed' });
  assert.deepEqual(await applierWith({ stored: false, armed: true }).apply('off'), { ok: false, reason: 'capture_armed' });
});

