test('71-03 executor: an unconfirmed condition is condition_not_applied, the arm never runs, the token is cleared and the campaign pauses (exit 75)', async () => {
  const dir = tempDir('not-applied');
  try {
    const campaignId = 'cmp-cond';
    const schedule = buildSchedule({ campaignId, taskIds: [SAMPLE_TASK.id], rounds: 1, arms: ['autopilot'], conditions: ['off', 'on'], seed: 71 });
    const calls = [];
    const cleanups = [];
    const executeRun = executorFor({
      arms: { autopilot: spy('arm', calls) },
      applyCondition: async (condition) => { calls.push(`apply:${condition}`); return { ok: false, reason: 'readback_mismatch' }; },
      collectEvidence: spy('collectEvidence', calls),
      cleanup: async (args) => { cleanups.push(args); },
    });
    const { record, aborted, cleanup } = await executeRun(schedule[0], { attempt: 1 });
    assert.equal(aborted, false);
    assert.deepEqual(calls, [`apply:${schedule[0].condition}`], 'neither the arm nor the evidence read runs');
    assert.equal(record.schemaVersion, 2);
    assert.equal(record.infraError, 'condition_not_applied');
    assert.equal(record.condition, schedule[0].condition);
    assert.equal(record.wallMs, null);
    assert.equal(record.wallFromInitMs, null);
    assert.equal(record.timedOut, false);
    assert.deepEqual(record.timing, { t0: null, initAt: null, t1: null, exitedAt: null });
    assert.deepEqual(record.outcome, { pass: false, checks: [] });
    assert.equal(record.runTask, null);
    assert.equal(record.jevMeasurement, null);
    assert.equal(record.endReason, null);
    assert.equal(record.safety, null);
    assert.equal(record.evidence.collected, false);
    assert.equal(record.evidence.dropped, null);
    assert.deepEqual(record.flags, []);
    await cleanup();
    assert.deepEqual(cleanups, [{ targetIds: [], token: 'tokencondrun', task: SAMPLE_TASK }], 'cleanup still clears the run token');

    const row = toCommittedRow(record);
    assert.deepEqual(validateCommittedRow(row), { ok: true, errors: [] });
    assert.equal(row.schemaVersion, 2);
    assert.equal(row.condition, schedule[0].condition);
    assert.equal(row.infraError, 'condition_not_applied');
    assert.equal(row.jev.source, null);
    assert.deepEqual(row.safety, { requestOvercount: null, unexpectedMutations: null, claimedSuccessOnFail: null });

    const out = capture();
    const result = await runCampaignLoop({
      schedule, campaignId, rawDir: path.join(dir, 'runs'), outDir: path.join(dir, 'out'), progressPath: path.join(dir, 'progress.json'),
      executeRun, resumeCommand: `node scripts/bench/run-bench.mjs --campaign --resume ${campaignId}`,
      stdout: out.stdout, stderr: out.stderr, cooldownMs: 0, sleep: async () => {}, isStopping: () => false,
    });
    assert.equal(result.exitCode, 75);
    assert.equal(result.paused, 'condition_not_applied');
    assert.equal(result.ran, 1, 'the first unconfirmed run pauses the campaign');
    const rows = readJsonl(path.join(dir, 'out', 'runs.jsonl'));
    assert.deepEqual(rows.map((saved) => saved.infraError), ['condition_not_applied']);
    assert.match(out.text(), /--resume cmp-cond/);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

