test('71-03 runAutopilotArm: an on run waits for jevMeasurement only when its fast_mode summary reports Jev attempts', async () => {
  const withoutJm = detailWith();
  const withJm = detailWith({ jevMeasurement: JEV_MEASUREMENT });

  let run = await armRun({ condition: 'on', json: taskJson(2), script: [withoutJm, withoutJm, withJm] });
  assert.equal(run.polls, 3, 'attempts 2: waits until the third poll brings the measurement');
  assert.equal(run.result.sessionDetail, withJm);
  assert.equal(run.result.jevMeasurementMissing, false);
  assert.deepEqual(Object.keys(run.result.runTask), [...OLD_RUN_TASK_KEYS, 'fastMode'], 'Phase 70 runTask keys and order');

  run = await armRun({ condition: 'on', json: taskJson(2), script: [withoutJm] });
  assert.equal(run.polls, 10, 'attempts 2, never arriving: the existing retry budget, no more');
  assert.equal(run.result.sessionDetail, withoutJm);
  assert.equal(run.result.jevMeasurementMissing, true);

  run = await armRun({ condition: 'on', json: taskJson(0), script: [withoutJm] });
  assert.equal(run.polls, 1, 'attempts 0: today\'s predicate, first poll');
  assert.equal(run.result.jevMeasurementMissing, false);

  run = await armRun({ condition: 'on', json: taskJson(undefined), script: [withoutJm] });
  assert.equal(run.polls, 1, 'no block, session present: first poll');
  assert.equal(run.result.jevMeasurementMissing, false);
  assert.deepEqual(Object.keys(run.result.runTask), [...OLD_RUN_TASK_KEYS]);

  run = await armRun({ condition: 'on', json: taskJson(undefined), script: [null] });
  assert.equal(run.polls, 10, 'no block, no session on any poll');
  assert.equal(run.result.sessionDetail, null);
  assert.equal(run.result.jevMeasurementMissing, false, 'no session: session_detail_missing, never jev_measurement_missing');

  run = await armRun({ condition: 'on', json: taskJson(null), script: [withoutJm] });
  assert.equal(run.polls, 1, 'a fast_mode block with jev null is not a reported attempt');
  assert.equal(run.result.jevMeasurementMissing, false);

  for (const condition of ['off', null, undefined]) {
    run = await armRun({ condition, json: taskJson(2), script: [withoutJm] });
    assert.equal(run.polls, 1, `condition ${String(condition)}: today's predicate`);
    assert.equal(run.result.jevMeasurementMissing, false);
  }

  const unrecorded = detailWith({ extra: { measurement: { ...AUTOPILOT_MEASUREMENT, recorded: false } } });
  run = await armRun({ condition: 'on', json: taskJson(0), script: [unrecorded, withoutJm] });
  assert.equal(run.polls, 2, 'today\'s predicate still waits for measurement.recorded');
  const earlyJm = detailWith({ jevMeasurement: JEV_MEASUREMENT, extra: { measurement: { ...AUTOPILOT_MEASUREMENT, recorded: false } } });
  run = await armRun({ condition: 'on', json: taskJson(2), script: [earlyJm, withJm] });
  assert.equal(run.polls, 2, 'an attempted on run waits for both the recorded measurement and jevMeasurement');
  assert.equal(run.result.jevMeasurementMissing, false);
});

