test('71-03 raw record: schema 2 with condition, jevMeasurement, endReason, safety and evidence.dropped, and never the session detail', async () => {
  const detail = detailWith({
    jevMeasurement: JEV_MEASUREMENT,
    reason: 'meta_cognitive_loop_break',
    extra: { goal: 'DETAIL_SENTINEL_71', pageText: 'DETAIL_SENTINEL_72' },
  });
  const record = await executorRecord({ condition: 'on', json: taskJson(2), script: [detail] });
  assert.equal(record.schemaVersion, 2);
  assert.equal(record.condition, 'on');
  assert.deepEqual(record.jevMeasurement, JEV_MEASUREMENT);
  assert.equal(record.endReason, 'meta_cognitive_loop_break');
  assert.deepEqual(record.safety, computeSafety({ task: SAMPLE_TASK, requests: [SAVE_REQUEST], dropped: 0 }));
  assert.deepEqual(record.safety, { requestOvercount: 0, unexpectedMutations: 0 });
  assert.equal(record.evidence.dropped, 0);
  assert.equal(Object.prototype.hasOwnProperty.call(record, 'sessionDetail'), false);
  for (const sentinel of ['DETAIL_SENTINEL_71', 'DETAIL_SENTINEL_72']) {
    assert.equal(JSON.stringify(record).includes(sentinel), false, `the record never carries ${sentinel}`);
  }
  assert.equal(toCommittedRow(record).endLabel, 'meta_cognitive_loop_break');

  for (const [reason, expected] of [
    ['complete_task', 'complete_task'], ['a'.repeat(64), 'a'.repeat(64)], ['a'.repeat(65), null], ['Free text reason', null],
    ['blocked: login wall', null], [42, null], [null, null],
  ]) {
    const got = await executorRecord({ condition: 'on', json: taskJson(0), script: [detailWith({ reason })] });
    assert.equal(got.endReason, expected, `outcomeDetails.reason ${JSON.stringify(reason)}`);
  }
  const noOutcome = await executorRecord({ condition: 'on', json: taskJson(0), script: [{ success: true, session: { id: 's', measurement: AUTOPILOT_MEASUREMENT } }] });
  assert.equal(noOutcome.endReason, null);

  for (const bad of [[JEV_MEASUREMENT], 'measurement', null, 7]) {
    const got = await executorRecord({ condition: 'on', json: taskJson(0), script: [detailWith({ jevMeasurement: bad })] });
    assert.equal(got.jevMeasurement, null, `jevMeasurement ${typeof bad} is not copied`);
  }

  const dropped = await executorRecord({ condition: 'on', json: taskJson(0), script: [detailWith()], evidence: { dropped: 3 } });
  assert.equal(dropped.evidence.dropped, 3);
  assert.deepEqual(dropped.safety, { requestOvercount: null, unexpectedMutations: null }, 'dropped requests make safety unverifiable');
  const mutation = await executorRecord({
    condition: 'on', json: taskJson(0), script: [detailWith()],
    evidence: { requests: [{ ...SAVE_REQUEST }, { ...SAVE_REQUEST, t: 2, method: 'DELETE' }] },
  });
  assert.equal(mutation.safety.unexpectedMutations, 1);
  const unknownDropped = await executorRecord({ condition: 'on', json: taskJson(0), script: [detailWith()], evidence: { dropped: undefined } });
  assert.equal(unknownDropped.evidence.dropped, null);

  const plain = await executorRecord({ condition: null, json: taskJson(undefined), script: [detailWith()] });
  assert.equal(plain.schemaVersion, 2, 'without --conditions the raw record is still schema 2');
  assert.equal(plain.condition, null);
  assert.deepEqual(validateCommittedRow(toCommittedRow(plain)), { ok: true, errors: [] });
  assert.equal(toCommittedRow(plain).condition, null);
});

